private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int limit = bb.limit();
    while (i < limit) {
        int b1 = bb.get(i) & 0xFF;
        if (b1 <= 0x7F) {
            sb.append((char) b1);
            i++;
            continue;
        }
        if (b1 >= 0xC0 && b1 <= 0xDF) { // 2-byte sequence
            if (i + 1 >= limit) {
                break; // incomplete sequence
            }
            int b2 = bb.get(i + 1) & 0xFF;
            if ((b2 & 0xC0) != 0x80) {
                break; // invalid continuation byte
            }
            int codePoint = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
            sb.append((char) codePoint);
            i += 2;
            continue;
        }
        if (b1 >= 0xE0 && b1 <= 0xEF) { // 3-byte sequence
            if (i + 2 >= limit) {
                break; // incomplete sequence
            }
            int b2 = bb.get(i + 1) & 0xFF;
            int b3 = bb.get(i + 2) & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                break; // invalid continuation bytes
            }
            int codePoint = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            sb.append(Character.toChars(codePoint));
            i += 3;
            continue;
        }
        if (b1 >= 0xF0 && b1 <= 0xF7) { // 4-byte sequence
            if (i + 3 >= limit) {
                break; // incomplete sequence
            }
            int b2 = bb.get(i + 1) & 0xFF;
            int b3 = bb.get(i + 2) & 0xFF;
            int b4 = bb.get(i + 3) & 0xFF;
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
                break; // invalid continuation bytes
            }
            int codePoint = ((b1 & 0x07) << 18)
                    | ((b2 & 0x3F) << 12)
                    | ((b3 & 0x3F) << 6)
                    | (b4 & 0x3F);
            sb.append(Character.toChars(codePoint));
            i += 4;
            continue;
        }
        // Bytes starting with 0x80-0xBF are continuation bytes out of place or 0xF8-0xFF are invalid in strict UTF-8.
        break; // invalid leading byte
    }
    return i;
}

int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // Basic sanity checks on the parameters
    if (offset < 0) {
        throw new IllegalArgumentException("offset must be non-negative");
    }
    if (numLocal < 0) {
        throw new IllegalArgumentException("numLocal must be non-negative");
    }
    if (numStack < 0) {
        throw new IllegalArgumentException("numStack must be non-negative");
    }

    // Ensure that we have a frame container to initialise
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame has not been initialised");
    }

    try {
        // Initialise the frame with the provided information
        currentFrame.setOffset(offset);
        currentFrame.setLocalCount(numLocal);
        currentFrame.setStackCount(numStack);

        // The "next element" index for writing is typically the start of local
        // entries in the frame; we return zero to indicate that the first entry
        // should be written at index 0.  This index may be adjusted by the caller
        // if additional information is required.
        return 0;
    } catch (RuntimeException e) {
        // Wrap any unexpected runtime error in an IllegalStateException
        throw new IllegalStateException("Failed to initialise frame", e);
    }
}

private void enlarge(final int size){
    if (size <= 0){
        return; // nothing to enlarge
    }
    // current length of data stored
    final int currentLen = len; // 'len' is the number of valid bytes currently stored
    final int currentCap = bytes != null ? bytes.length : 0;
    final int required = currentLen + size;

    if (required <= currentCap){
        return; // already enough capacity
    }

    // compute a new capacity, usually growing by 50%
    int newCap = Math.max(required, currentCap * 3 / 2);
    if (newCap == 0){
        newCap = required; // initial allocation, when array is empty
    }

    byte[] newBytes = new byte[newCap];
    if (bytes != null && currentLen > 0){
        System.arraycopy(bytes, 0, newBytes, 0, currentLen);
    }
    bytes = newBytes;
}

