public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return null;
    }
    try {
        // Create a new mapping that contains all fields from the input
        // except the _source configuration to avoid update conflicts.
        Map<String, Object> diffProps = new LinkedHashMap<>();
        Map<String, Object> props = mappings.getProperties();
        if (props != null) {
            for (Map.Entry<String, Object> entry : props.entrySet()) {
