protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate FETCH_DATA_DURATION
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be greater than zero");
    }
    // Validate input bounds
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non‑negative");
    }
    if (start > end) {
        throw new IllegalArgumentException("Start time must not be greater than end time");
    }

    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    if (start == end) {
        return ranges; // No range to split
    }

    long currentStart = start;
    while (currentStart < end) {
        long remaining = end - currentStart;
        long segmentDuration = Math.min(remaining, FETCH_DATA_DURATION);
        long currentEnd = currentStart + segmentDuration;
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }

    return ranges;
}

