static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    try {
        // Parse year, month, day from YYYYMMDD
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Construct a LocalDate
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);

        // Calculate the starting day of the period
        int dayOfMonth = date.getDayOfMonth();
        int startDay = 1 + ((dayOfMonth - 1) / dayStep) * dayStep;

        // Create new date with adjusted day
        java.time.LocalDate newDate = date.withDayOfMonth(startDay);

        // Convert back to long YYYYMMDD
        return newDate.getYear() * 10000L
                + newDate.getMonthValue() * 100L
                + newDate.getDayOfMonth();
    } catch (java.time.DateTimeException e) {
        // If parsing fails, return the original value
