public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (len < 0) {
        throw new IllegalArgumentException("Length must be non-negative");
    }
    int end;
    try {
        end = Math.addExact(index, len);
    } catch (ArithmeticException e) {
        throw new IndexOutOfBoundsException("index + len overflow");
    }
    if (index < 0 || end > str.length()) {
        throw new IndexOutOfBoundsException("index or length out of bounds");
    }

    int byteCount = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            i += 2;
        } else {
            codePoint = ch;
            i++;
        }

        if (codePoint <= 0x7F) {
            byteCount += 1;
        } else if (codePoint <= 0x7FF) {
            byteCount += 2;
        } else if (codePoint <= 0xFFFF) {
            byteCount += 3;
        } else {
            byteCount += 4;
        }
    }
    return byteCount;
}

