    // If the source array is null, write nullbytes (zeros)
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.put((byte) 0);
        }
        return this;
    }
    // Validate offset and length against the source array bounds
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IllegalArgumentException("byteOffset out of bounds");
    }
    if (byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException("byteLength out of bounds");
    }
    // Copy the requested bytes into the vector
    for (int i = 0; i < byteLength; i++) {
        this.put(byteArrayValue[byteOffset + i]);
    }
    return this;
}

