        if (o1 == null) {
            return (o2 == null) ? 0 : -1;
        }
        if (o2 == null) {
            return 1;
        }
        int cmp = o1.compareTo(o2);
        return (cmp < 0) ? -1 : ((cmp > 0) ? 1 : 0);
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid comparison", e);
    }
}

