public static String capitalize(String name){
    if (name == null || name.isEmpty()) {
        return name;
    }
    if (name.length() > 1 && Character.isUpperCase(name.charAt(0))
            && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    return Character.toUpperCase(name.charAt(0)) + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput must not be null");
    }
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    try {
        // Iterate over the linked buffer chain and write each block to the output
        while (current != null) {
            // Attempt to obtain the underlying byte array and its current position.
            byte[] bytes = current.getArray();          // Get the byte array from the current block
            int pos = current.getPosition();            // Get the number of valid bytes written in this block
            if (pos > 0) {
                out.write(bytes, 0, pos);               // Write the valid part of the block to the output
                totalSize += pos;                       // Accumulate the total number of bytes written
            }
            current = current.getNext();                // Move to the next block in the chain
        }
    } catch (Exception e) {
        // Preserve original IOException, otherwise wrap in an IOException
        if (e instanceof IOException) {
            throw (IOException) e;
        }
        throw new IOException("Failed to write LinkedBuffer to DataOutput", e);
    }
    return totalSize;
}

