public String toString(){
    StringBuilder sb = new StringBuilder();
    sb.append('[');
    try {
        Iterator<?> it = this.iterator();
        while (it.hasNext()) {
            sb.append(it.next());
            if (it.hasNext()) {
                sb.append(", ");
            }
        }
    } catch (Exception e) {
        sb.append("Error");
    }
    sb.append(']');
    return sb.toString();
}

