}

public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    try {
        // Format timestamp into human‑readable form (yyyy-MM-dd HH:mm:ss.SSS)
        long tsMillis = event.getTimeStamp();
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sb.append(sdf.format(new java.util.Date(tsMillis)));
        sb.append(' ');

        // Log level
        sb.append(event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN");

        // Thread name
        sb.append(" [");
        sb.append(event.getThreadName() != null ? event.getThreadName() : "UNKNOWN");
        sb.append("] ");

        // Logger name
        sb.append(event.getLoggerName() != null ? event.getLoggerName() : "UNKNOWN");
        sb.append(" - ");

        // Formatted message
        sb.append(event.getFormattedMessage() != null ? event.getFormattedMessage() : "");

        // Throwable, if present
        ch.qos.logback.classic.spi.IThrowableProxy tp = event.getThrowableProxy();
        if (tp != null) {
            sb.append(System.lineSeparator());
            sb.append(tp.toString());
        }
    } catch (Exception ex) {
        sb.setLength(0);
        sb.append("Error formatting event: ").append(ex.toString());
    }
    return sb.toString();
}

public static double[] toPrimitive(final Double[] array){
    if (array == null) {
        return null;
    }
    double[] primitiveArray = new double[array.length];
    for (int i = 0; i < array.length; i++) {
        Double boxed = array[i];
        if (boxed == null) {
            throw new NullPointerException("Array element at index " + i + " is null");
        }
        primitiveArray[i] = boxed.doubleValue();
    }
    return primitiveArray;
}

private void addInitializedType(final int abstractType) {
