        JSONWriter writer;
        if (features == null || features.length == 0) {
            writer = new JSONWriter(sw);
        } else {
            writer = new JSONWriter(sw, features);
        }
        // Write this object into the writer
        writer.write(this);
        return sw.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to serialize JSON", e);
    }
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("Target type not assignable to java.lang.Character: " + type);
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }
    if (value instanceof CharSequence) {
        String str = value.toString();
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new Exception("String length must be 1 to convert to Character: '" + str + "'");
        }
    }
    // Fallback: try toString and take first char if single char
    String str = value.toString();
    if (str.length() == 1) {
        return Character.valueOf(str.charAt(0));
    }
    throw new Exception("Cannot convert value to Character: " + value);
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    try {
        if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
            return false;
        }
        String lowerStr = str.toLowerCase();
        for (String s : searchStrArray) {
            if (s == null) {
                continue;
            }
            String lowerS = s.toLowerCase();
            if (lowerS.isEmpty()) {
                return true;
            }
            if (lowerStr.contains(lowerS)) {
                return true;
            }
        }
        return false;
    } catch (Exception e) {
        // Unexpected error, return false
        return false;
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++; // make it odd
    }
    while (true) {
        boolean isPrime = true;
        if (candidate <= 3) {
            if (candidate >= 2) {
                return candidate;
            }
        } else {
            if ((candidate & 1) == 0 || candidate % 3 == 0) {
                isPrime = false;
            } else {
                for (int i = 5; (long) i * i <= candidate; i += 6) {
                    if (candidate % i == 0 || candidate % (i + 2) == 0) {
                        isPrime = false;
                        break;
                    }
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
}

