public static Object findFirstMatch(Collection source, Collection candidates) {
    if (source == null || candidates == null) {
        return null;
    }
    try {
        Iterator it = candidates.iterator();
        while (it.hasNext()) {
            Object candidate = it.next();
            try {
                if (source.contains(candidate)) {
                    return candidate;
                }
            } catch (Exception ignored) {
                // Ignore errors from contains (e.g., NullPointerException in some collections)
            }
        }
    } catch (Exception ignored) {
        // Ignore errors from iterating over candidates
    }
    return null;
}

public static String trimTrailingWhitespace(String str){
    if (str == null) {
        return null;
    }
    int end = str.length();
    while (end > 0 && Character.isWhitespace(str.charAt(end - 1))) {
        end--;
    }
    return (end == str.length() ? str : str.substring(0, end));
}

public void init(){
    String distPath = System.getProperty("dist.path");
    if (distPath == null || distPath.isEmpty()){
        try{
            distPath = System.getenv("DIST_PATH");
        }catch (SecurityException se){
            System.err.println("Unable to read environment variable DIST_PATH due to security restrictions: " + se.getMessage());
        }
    }
    if (distPath == null || distPath.isEmpty()){
        throw new IllegalStateException("Distribution path not specified. Set system property 'dist.path' or environment variable 'DIST_PATH'.");
    }
    java.io.File distDir = new java.io.File(distPath);
    if (!distDir.exists() || !distDir.isDirectory()){
        throw new IllegalStateException("Distribution path does not exist or is not a directory: " + distPath);
    }
    if (!distDir.canRead()){
        throw new IllegalStateException("No read permission for distribution path: " + distPath);
    }
}

@Override
public String readString() throws IOException {
    // Read the length of the string
    int length = readInt();
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }

    // Read exactly 'length' bytes from the underlying stream
    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = input.read(bytes, offset, length - offset);
        if (read == -1) {
            throw new IOException("Unexpected end of stream while reading string");
        }
        offset += read;
    }

    // Convert bytes to string using UTF-8 encoding
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

private static int digitValue(final char c) {
    // Handle ASCII digits
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // Handle ASCII lowercase letters
    if (c >= 'a' && c <= 'z') {
        return 10 + (c - 'a');
    }
    // Handle ASCII uppercase letters
    if (c >= 'A' && c <= 'Z') {
        return 10 + (c - 'A');
    }
    // Non-ASCII or unsupported characters are considered invalid
    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new java.util.HashMap<>();
    if(jsonObject == null){
        return content;
    }
    try{
        for(java.util.Map.Entry<String, com.google.gson.JsonElement> entry : jsonObject.entrySet()){
            String key = entry.getKey();
            com.google.gson.JsonElement value = entry.getValue();
            if(value == null || value.isJsonNull()){
                content.put(key, null);
                continue;
            }
            if("ats".equals(key)){
                if(value.isJsonArray()){
                    java.util.List<Object> atsList = new java.util.ArrayList<>();
                    for(com.google.gson.JsonElement elem : value.getAsJsonArray()){
                        if(elem.isJsonObject()){
                            // Convert JsonObject to Map recursively
                            atsList.add(buildContent(elem.getAsJsonObject()));
                        }else if(elem.isJsonPrimitive()){
                            atsList.add(getPrimitiveValue(elem.getAsJsonPrimitive()));
                        }else if(elem.isJsonArray()){
                            // Nested arrays are represented as list of primitives
                            java.util.List<Object> nested = new java.util.ArrayList<>();
                            for(com.google.gson.JsonElement nestedElem : elem.getAsJsonArray()){
                                nested.add(getPrimitiveValue(nestedElem.getAsJsonPrimitive()));
                            }
                            atsList.add(nested);
                        }else{
                            // Fallback to string representation
                            atsList.add(elem.toString());
                        }
                    }
                    content.put(key, atsList);
                }else{
                    // If 'ats' is not an array, just store whatever it is
                    content.put(key, value.getAsString());
                }
                continue;
            }
            if(value.isJsonObject()){
                content.put(key, buildContent(value.getAsJsonObject()));
            }else if(value.isJsonArray()){
                // Flatten array into list of primitives or maps
                java.util.List<Object> list = new java.util.ArrayList<>();
                for(com.google.gson.JsonElement elem : value.getAsJsonArray()){
                    if(elem.isJsonObject()){
                        list.add(buildContent(elem.getAsJsonObject()));
                    }else if(elem.isJsonPrimitive()){
                        list.add(getPrimitiveValue(elem.getAsJsonPrimitive()));
                    }else if(elem.isJsonArray()){
                        // nested array
                        java.util.List<Object> nested = new java.util.ArrayList<>();
                        for(com.google.gson.JsonElement nestedElem : elem.getAsJsonArray()){
                            nested.add(getPrimitiveValue(nestedElem.getAsJsonPrimitive()));
                        }
                        list.add(nested);
                    }else{
                        list.add(elem.toString());
                    }
                }
                content.put(key, list);
            }else if(value.isJsonPrimitive()){
                content.put(key, getPrimitiveValue(value.getAsJsonPrimitive()));
            }else{
                content.put(key, value.toString());
            }
        }
    }catch(Exception e){
        // In case of unexpected data format, return what has been built so far
        return content;
    }
    return content;
}

