public final byte[] toByteArray(){
    // If no buffers have been added, return an empty array.
    if (buffers == null || buffers.isEmpty()){
        return new byte[0];
    }

    // Calculate total length required.
    int totalLength = 0;
    for (byte[] buf : buffers){
        if (buf != null){
            totalLength += buf.length;
        }
    }

    // Allocate result array and copy each buffer into it.
    byte[] result = new byte[totalLength];
    int offset = 0;
    for (byte[] buf : buffers){
        if (buf != null){
            System.arraycopy(buf, 0, result, offset, buf.length);
            offset += buf.length;
        }
    }
    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 >= len) {
                throw new Exception("Trailing backslash at end of string");
            }
            char next = str.charAt(++i);
            switch (next) {
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new Exception("Invalid Unicode escape sequence: missing 4 hex digits");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: " + hex);
                    }
                    i += 4;
                    break;
                default:
                    // Treat unknown escape sequences as the literal character after backslash
                    sb.append(next);
                    break;
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset) {
