public short readShort(final int offset) {
    // Ensure the offset is within the bounds of the byte array and that
    // there are at least two bytes available to read a signed short.
    if (offset < 0 || offset + 1 >= data.length) {
        throw new IndexOutOfBoundsException(
            "Attempted to read short at offset " + offset +
            ", but data length is " + data.length);
    }
    // The JVM class file format stores multi-byte numeric values in big-endian
    // order.  We therefore combine the two bytes accordingly, masking with
    // 0xFF to avoid sign extension of the individual bytes.
    return (short) (((data[offset] & 0xFF) << 8)
                    | (data[offset + 1] & 0xFF));
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType){
    if (array != null && !array.getClass().isArray()){
        throw new IllegalArgumentException("parameter \"array\" must be an array");
    }
    Class<?> componentType;
    int oldLength;
    if (array == null){
        if (newArrayComponentType == null){
            throw new NullPointerException("newArrayComponentType is null");
        }
        componentType = newArrayComponentType;
        oldLength = 0;
    }else{
        componentType = array.getClass().getComponentType();
        oldLength = java.lang.reflect.Array.getLength(array);
    }
    Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLength + 1);
    if (array != null){
        System.arraycopy(array, 0, newArray, 0, oldLength);
    }
    return newArray;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    return 32 - Integer.numberOfLeadingZeros(n);
}

private Set<V> intersection(Set<V> set1, Set<V> set2){
    if (set1 == null || set2 == null) {
        return new HashSet<V>();
    }
    // Choose the smaller set to iterate over for better performance
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger = set1.size() <= set2.size() ? set2 : set1;
    Set<V> result = new HashSet<V>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

static String[] toNoNullStringArray(Collection<?> collection){  
    if (collection == null) {  
        return new String[0];  
    }  
    List<String> list = new ArrayList<>(collection.size());  
    for (Object obj : collection) {  
        if (obj != null) {  
            list.add(obj.toString());  
        }  
    }  
    return list.toArray(new String[0]);  
}

private static boolean isAllZeros(String s){
    if (s == null) {
        return true;
    }
    if (s.isEmpty()) {
        return false;
    }
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) != '0') {
            return false;
        }
    }
    return true;
}

protected Object filter(Object msg){
    if (msg == null) {
        return null;
    }
    try {
        BroadcastFilter bf = new BroadcastFilter();
        return bf.filter(msg);
    } catch (Exception e) {
        // In case the broadcast filter fails, return the original message
        return msg;
    }
}

private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObjectBuilder builder = Json.createObjectBuilder();
    if (properties == null){
        return builder.build();
    }
    for (KeyStringValuePair pair : properties){
        try{
            if (pair == null){
                continue;
            }
            String key = pair.getKey();
            if (key == null){
                continue;
            }
            String value = pair.getValue();
            if (value == null){
                builder.add(key, JsonValue.NULL);
            } else {
                builder.add(key, value);
            }
        } catch (Exception ignored){
            // ignore invalid entries
        }
    }
    return builder.build();
}

protected int removeUnusedNodes(){
    int removed = 0;
    try {
        if (root == null) {
            return removed;
        }
        if (!root.isActive()) {
            root = null;
            removed++;
            return removed;
        }
        LinkedList<Category> stack = new LinkedList<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category node = stack.pop();
            List<Category> children = node.getChildren();
            if (children == null) continue;
            for (Iterator<Category> it = children.iterator(); it.hasNext();) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        return 0;
    }
    return removed;
}

