final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Validate indices and offsets
    if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= constantPoolInfoOffsets.length) {
        throw new IllegalArgumentException("Invalid constant pool index: " + constantPoolEntryIndex);
    }
    final int offset = constantPoolInfoOffsets[constantPoolEntryIndex];
    if (offset < 0 || offset + 3 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry offset for index: " + constantPoolEntryIndex);
    }
    // Verify that the entry is a CONSTANT_Utf8
    final int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a UTF-8 entry");
    }
    // Read the length of the UTF-8 encoded string
    final int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) |
                       (classFileBuffer[offset + 2] & 0xFF);
    if (length < 0) {
        throw new IllegalArgumentException("Negative UTF-8 length at index " + constantPoolEntryIndex);
    }
    final int byteStart = offset + 3;
    final int byteEnd = byteStart + length;
    if (byteEnd > classFileBuffer.length) {
        throw new IllegalArgumentException("UTF-8 string at index " + constantPoolEntryIndex + " exceeds class file size");
    }
    // Ensure charBuffer is large enough
    if (charBuffer == null || charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small to hold UTF-8 entry at index " + constantPoolEntryIndex);
    }
    // Decode the bytes into a Java String using UTF-8
    final String utfString = new String(classFileBuffer, byteStart, length, java.nio.charset.StandardCharsets.UTF_8);
    // Copy the resulting characters into the supplied buffer
    final int actualLength = utfString.length();
    if (actualLength > charBuffer.length) {
        throw new IllegalStateException("Decoded UTF-8 string length exceeds buffer capacity");
    }
    utfString.getChars(0, actualLength, charBuffer, 0);
    return utfString;
}

