        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    // Initialize a circulator starting at the specified node and direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = circ.getNode();

    // Iterate around the outer face until we reach the stop node or find a node
    // satisfying the predicate. A safety counter protects against accidental
    // infinite loops if the graph is malformed.
    int safety = 0;
    final int MAX_ITERATIONS = 10000;
    while (!current.equals(stop) && !predicate.test(current)) {
        circ.next();                     // advance to the next node along the outer face
        current = circ.getNode();        // fetch the new current node
        if (++safety > MAX_ITERATIONS) {
            break;                       // give up after too many iterations
        }
    }

    return circ;   // returns a circulator pointing at the matched node or at the stop node
}

