public static String deleteAny(String inString, String charsToDelete) {
    if (inString == null) {
        return null;
    }
    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }
    // Build a set of code points to delete
    java.util.Set<Integer> deletions = new java.util.HashSet<>();
    for (int i = 0; i < charsToDelete.length(); ) {
        int cp = charsToDelete.codePointAt(i);
        deletions.add(cp);
        i += Character.charCount(cp);
    }

    StringBuilder sb = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); ) {
        int cp = inString.codePointAt(i);
        if (!deletions.contains(cp)) {
            sb.appendCodePoint(cp);
        }
        i += Character.charCount(cp);
    }
    return sb.toString();
}

