private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        java.lang.reflect.Field[] fields = clazz.getDeclaredFields();
        java.util.List<Integer> indices = new java.util.ArrayList<>();
        for (java.lang.reflect.Field field : fields) {
            for (java.lang.annotation.Annotation ann : field.getAnnotations()) {
                if (ann.annotationType().getSimpleName().equals("ShardingKey")) {
                    try {
                        int idx = (int) ann.annotationType().getMethod("index").invoke(ann);
                        indices.add(idx);
                    } catch (java.lang.NoSuchMethodException | java.lang.IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
                        throw new IllegalStateException("Failed to read sharding key index for field " + field.getName(), e);
                    }
                }
            }
        }
        if (indices.isEmpty()) {
            return;
        }
        java.util.Collections.sort(indices);
        int expected = 0;
        for (int i = 0; i < indices.size(); i++) {
            int idx = indices.get(i);
            if (idx != expected) {
                throw new IllegalStateException("Sharding key indices are not continuous for model " + modelName);
            }
            expected++;
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model class not found: " + modelName, e);
    }
}

