public int compare(Object aObj1, Object aObj2){
    // Handle nulls first
    if (aObj1 == aObj2) { // covers both being null or the same reference
        return 0;
    }
    if (aObj1 == null) {
        return -1; // null is considered less than any non-null
    }
    if (aObj2 == null) {
        return 1; // any non-null is greater than null
    }
    // Attempt natural ordering if both objects implement Comparable
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> comp = (Comparable<Object>) aObj1;
            return comp.compareTo(aObj2);
        } catch (ClassCastException e) {
            // Objects are Comparable but not mutually comparable; fall through to string comparison
        } catch (Exception e) {
            // Wrap any other unexpected runtime issue
            throw new RuntimeException("Failed to compare Comparable objects", e);
        }
    }
    // Fallback: compare string representations
    try {
        return aObj1.toString().compareTo(aObj2.toString());
    } catch (Exception e) {
        throw new RuntimeException("Failed to compare objects via toString()", e);
    }
}

