public int appendLoopOnAppenders(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("event is null");
    }
    int count = 0;
    if (this.appenders != null) {
        for (Object obj : this.appenders) {
            Appender appender;
            if (obj instanceof Appender) {
                appender = (Appender) obj;
            } else {
                continue;
            }
            if (appender == null) {
                continue;
            }
            try {
                appender.doAppend(event);
                count++;
            } catch (Throwable t) {
                // If an appender throws an exception, ignore it and continue with the others
                // This mirrors the behaviour of many logging frameworks
            }
        }
    }
    return count;
}

