    if (inputStream == null) {
        return new byte[0];
    }

    try (java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream()) {
        // Buffer size of 8 KB is a common default.
        byte[] buffer = new byte[8192];
        int bytesRead;
        // Read chunks from the input stream until EOF.
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            baos.write(buffer, 0, bytesRead);
        }
        // Return the accumulated bytes.
        return baos.toByteArray();
    } catch (java.io.IOException e) {
        // Wrap checked exception in an unchecked one to avoid leaking IOException.
        throw new RuntimeException("Failed to copy bytes to array", e);
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
