    }
    if (tour.isEmpty()) {
        return null;
    }
    E firstEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V endVertex = graph.getEdgeTarget(firstEdge);

    java.util.List<E> edgeList = new java.util.ArrayList<E>(tour);
    double weight = 0.0;
    for (E e : tour) {
        weight += graph.getEdgeWeight(e);
