int addConstantNameAndType(final String name, final String descriptor) {
    // Validate input
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }

    // Use a composite key to check for existing entries
    final String key = name + "#" + descriptor;
    Integer existingIndex = nameAndTypeIndexMap.get(key);
    if (existingIndex != null) {
        // Already present – return the existing index
        return existingIndex;
    }

    try {
        // Add UTF-8 entries for name and descriptor first
        int nameIndex = addConstantUtf8(name);
        int descriptorIndex = addConstantUtf8(descriptor);

        // Tag value for CONSTANT_NameAndType_info
        final int TAG_NAME_AND_TYPE = 12;

        // Create the new NameAndType constant pool entry
        ConstantPoolEntry entry = new ConstantPoolEntry(TAG_NAME_AND_TYPE, nameIndex, descriptorIndex);

        // Add it to the pool and store the index in the map
        int newIndex = constantPool.size();
        constantPool.add(entry);
        nameAndTypeIndexMap.put(key, newIndex);

        return newIndex;
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception
        throw new RuntimeException("Failed to add CONSTANT_NameAndType_info", e);
    }
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    // Strip surrounding quotes if present
    if (input.length() >= 2 && input.charAt(0) == '"' && input.charAt(input.length() - 1) == '"') {
        input = input.substring(1, input.length() - 1);
    }

    StringBuilder sb = new StringBuilder();
    int len = input.length();
    int i = 0;
    while (i < len) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 2;
                    break;
                case 't':
                    sb.append('\t');
                    i += 2;
                    break;
                case '\\':
                    sb.append('\\');
                    i += 2;
                    break;
                case '"':
                    sb.append('"');
                    i += 2;
                    break;
                case '\'':
                    sb.append('\'');
                    i += 2;
                    break;
                case '0':
                    sb.append('\0');
                    i += 2;
                    break;
                case 'u':
                    if (i + 5 < len) { // need 4 hex digits after 'u'
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                        } catch (NumberFormatException e) {
                            sb.append('u');
                            sb.append(hex);
                        }
                        i += 6;
                    } else {
                        sb.append('u');
                        i += 2;
                    }
                    break;
                case 'x':
                    if (i + 3 < len) { // need 2 hex digits after 'x'
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                        } catch (NumberFormatException e) {
                            sb.append('x');
                            sb.append(hex);
                        }
                        i += 4;
                    } else {
                        sb.append('x');
                        i += 2;
                    }
                    break;
                default:
                    sb.append(next);
                    i += 2;
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2){
    // If both arrays are null, return null as specified
    if (array1 == null && array2 == null) {
        return null;
    }

    int len1 = (array1 == null ? 0 : array1.length);
    int len2 = (array2 == null ? 0 : array2.length);

    // Create a new array with combined length
    String[] result = new String[len1 + len2];
    int destPos = 0;

    // Copy elements from the first array if present
    if (array1 != null) {
        System.arraycopy(array1, 0, result, destPos, len1);
        destPos += len1;
    }

    // Copy elements from the second array if present
    if (array2 != null) {
        System.arraycopy(array2, 0, result, destPos, len2);
    }

    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    if (minLabel == 0) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<>();
        bucketsByLabel.set(0, target);
    }
    for (Integer v : source) {
        if (v == null) {
            continue;
        }
        target.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }
    source.clear();
}

