private void pop(final int elements){
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop cannot be negative: " + elements);
    }
    if (elements == 0) {
        return;
    }
    try {
        if (outputFrameStack == null) {
            throw new IllegalStateException("Output frame stack has not been initialized.");
        }
        int available = outputFrameStack.size();
        if (available < elements) {
            throw new IllegalStateException(
                "Insufficient elements in output frame stack. Requested: " + elements + ", available: " + available);
        }
        for (int i = 0; i < elements; i++) {
            outputFrameStack.pop();
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to pop elements from output frame stack", e);
    }
}

public boolean isCompatible(DataTable dataset) {
    try {
        if (dataset == null) {
            return false;
        }

        // Retrieve the bucket of the current object
        String currentBucket = null;
        try {
            java.lang.reflect.Method getBucketMethod = this.getClass().getMethod("getBucket");
            Object value = getBucketMethod.invoke(this);
            currentBucket = value != null ? value.toString() : null;
        } catch (Exception e) {
            // If getBucket() does not exist, try to access a field named 'bucket'
            try {
                java.lang.reflect.Field bucketField = this.getClass().getDeclaredField("bucket");
                bucketField.setAccessible(true);
                Object value = bucketField.get(this);
                currentBucket = value != null ? value.toString() : null;
            } catch (Exception ignored) {
                // No bucket found
            }
        }

        // Retrieve the bucket of the provided dataset
        String datasetBucket = null;
        try {
            java.lang.reflect.Method getBucketMethod = dataset.getClass().getMethod("getBucket");
            Object value = getBucketMethod.invoke(dataset);
            datasetBucket = value != null ? value.toString() : null;
        } catch (Exception ignored) {
            // No getBucket() method available
        }

        // If either bucket is null, consider them not compatible
        if (currentBucket == null || datasetBucket == null) {
            return false;
        }

        return currentBucket.equals(datasetBucket);
    } catch (Exception e) {
        // Any other runtime issues result in incompatibility
        return false;
    }
}

