void removeSelf(){
    // Attempt to unlink this bucket from its containing data structure.
    // The bucket is assumed to be part of a doubly‑linked list maintained
    // by the owning structure.  The owning structure should provide
    // references (e.g., head and tail) that are updated when the
    // first or last element is removed.
    try {
        // If this bucket has a predecessor, bypass this bucket in the list.
        if (prev != null) {
            prev.next = this.next;
        } else if (owner != null) {                // This bucket is the head of the list.
            owner.head = this.next;
        }

        // If this bucket has a successor, bypass this bucket in the list.
        if (next != null) {
            next.prev = this.prev;
        } else if (owner != null) {                // This bucket is the tail of the list.
            owner.tail = this.prev;
        }

        // Null out local links to aid garbage collection.
        this.prev = null;
        this.next = null;
    } catch (Exception e) {
        // Wrap any unexpected failure in a runtime exception with context.
        throw new RuntimeException("Failed to remove bucket from data structure", e);
    }
}

