private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    /* If the node is not part of this list, we cannot unlink it safely.
       Basic validation can be added if a bi‑directional link is stored.
       For simplicity we proceed assuming the caller has verified membership. */
    try {
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;

        // Update previous node's next pointer or list head
        if (prev != null) {
            prev.next = next;
        } else {
            // node is the head
            head = next;
        }

        // Update next node's prev pointer or list tail
        if (next != null) {
            next.prev = prev;
        } else {
            // node is the tail
            tail = prev;
        }

        // Disconnect the node from the list
        node.prev = null;
        node.next = null;

        // Decrement the size, ensuring it stays non-negative
        if (size > 0) {
            size--;
        }
        return true;
    } catch (RuntimeException e) {
        // In case of unforeseen errors, do not corrupt list state
        return false;
    }
}

