private String parseToken(final char[] terminators){
    if (terminators == null || terminators.length == 0) {
        throw new IllegalArgumentException("Terminators cannot be null or empty");
    }
    StringBuilder token = new StringBuilder();
    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(System.in))) {
        int c;
        while ((c = reader.read()) != -1) {
            char ch = (char) c;
            boolean isTerminator = false;
            for (char t : terminators) {
                if (ch == t) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break;
            }
            token.append(ch);
        }
    } catch (java.io.IOException e) {
        throw new RuntimeException("Error reading token", e);
    }
    return token.toString();
}

