private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    try {
        for (int i = n - 1; i >= 0; i--) {
            total += bounds.get(i);
            // insert at the beginning to preserve order
            suffix.add(0, (int) total);
        }
    } catch (Exception e) {
        // In case of unexpected runtime issues, clear the suffix list and rethrow
        suffix.clear();
        throw new RuntimeException("Error computing suffix sums", e);
    }
    return new Pair<>(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array cannot be null");
    }
    int len = arr.length;
    if (from < 0 || to < 0 || from >= len || to >= len || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", length=" + len);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    // If the source list is empty, nothing to do
    if (list.head == null) {
        return;
    }
    // If this list is empty, simply adopt the source list's nodes
    if (this.head == null) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Connect the tail of this list to the head of the source list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    // Update size
    this.size += list.size;
    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

