        // provide a method getEdges() that returns a collection of edges of type E.
        for (E edge : graph.getEdges()){
            // Compute minimal separator lists for the neighborhood of this edge.
            // It is assumed that a helper method computeMinimalSeparatorsNeighborhood(E)
            // is available and returns a List of separator lists, each separator being
            // a List of integer pairs.
            List<List<Pair<Integer,Integer>>> minSeparators = computeMinimalSeparatorsNeighborhood(edge);
            for (List<Pair<Integer,Integer>> sep : minSeparators){
                separatorList.add(new Pair<>(sep, edge));
            }
        }
    }catch(Exception ex){
        // Log the exception and continue; the method returns whatever has
        // been collected up to the point of failure.
        System.err.println("Error computing global separator list: " + ex.getMessage());
    }
    return separatorList;
}

