public ByteVector putInt(final int intValue){
    // Ensure the internal byte array has enough space for 4 new bytes.
    if (a == null) {
        // Initial allocation if the array hasn't been created yet.
        a = new byte[4];
    } else if (pos + 4 > a.length) {
        // Grow the array, ensuring we accommodate the new data.
        int newLen = Math.max(a.length << 1, pos + 4);
        byte[] newArray = new byte[newLen];
        System.arraycopy(a, 0, newArray, 0, pos);
        a = newArray;
    }
    // Store the int in big‑endian order (network byte order).
    a[pos++] = (byte) (intValue >> 24);
    a[pos++] = (byte) (intValue >> 16);
    a[pos++] = (byte) (intValue >> 8);
    a[pos++] = (byte) intValue;
    return this;
}

