private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Handle invalid inputs gracefully
    if (graph == null || vertices == null) {
        return false;
    }

    // A graph with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    try {
        for (V v1 : vertices) {
            for (V v2 : vertices) {
                if (v1 == v2) {
                    continue; // Skip self-pairs
                }
                // For undirected graphs graph.containsEdge is symmetric
                if (!graph.containsEdge(v1, v2)) {
                    return false; // Missing edge -> not a clique
                }
            }
        }
        return true; // All pairs are connected
    } catch (Exception e) {
        // Any runtime exception (e.g., due to a malformed graph) results in false
        return false;
    }
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("Keys must be of type Integer");
        }
        Integer curr = (Integer) key;
        Integer best = null;
        for (K other : keys) {
            if (other == null || other == key) {
                continue;
            }
            if (!(other instanceof Integer)) {
                continue;
            }
            Integer val = (Integer) other;
            if (val < curr) {
                if (best == null || val > best) {
                    best = val;
                }
            }
        }
        result.add(best);
    }
    return result;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        throw new IllegalArgumentException("Descriptor must be non‑null and non‑empty");
    }
    try {
        int i = 0;
        if (descriptor.charAt(0) == '('){
            i = 1; // skip '('
            while (i < descriptor.length() && descriptor.charAt(i) != ')'){
                char c = descriptor.charAt(i);
                if (c == 'L'){ // reference type
                    i++;
                    while (i < descriptor.length() && descriptor.charAt(i) != ';'){
                        i++;
                    }
                    if (i >= descriptor.length()){
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    i++; // skip ';'
                    if (outputFrameStack.isEmpty()){
                        throw new IllegalStateException("Stack underflow while popping type");
                    }
                    outputFrameStack.pop();
                }else if (c == '['){ // array type
                    while (i < descriptor.length() && descriptor.charAt(i) == '['){
                        i++;
                    }
                    if (i < descriptor.length() && descriptor.charAt(i) == 'L'){
                        i++; // skip 'L'
                        while (i < descriptor.length() && descriptor.charAt(i) != ';'){
                            i++;
                        }
                        if (i >= descriptor.length()){
                            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                        }
                        i++; // skip ';'
                    }
                    if (outputFrameStack.isEmpty()){
                        throw new IllegalStateException("Stack underflow while popping array");
                    }
                    outputFrameStack.pop();
                }else{ // primitive type
                    if (outputFrameStack.isEmpty()){
                        throw new IllegalStateException("Stack underflow while popping primitive");
                    }
                    outputFrameStack.pop();
                    i++;
                }
            }
        }else{ // single type descriptor
            int pos = 0;
            char first = descriptor.charAt(0);
            if (first == 'L'){
                pos++;
                while (pos < descriptor.length() && descriptor.charAt(pos) != ';'){
                    pos++;
                }
                if (pos >= descriptor.length()){
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                if (outputFrameStack.isEmpty()){
                    throw new IllegalStateException("Stack underflow while popping type");
                }
                outputFrameStack.pop();
            }else if (first == '['){
                while (pos < descriptor.length() && descriptor.charAt(pos) == '['){
                    pos++;
                }
                if (pos < descriptor.length() && descriptor.charAt(pos) == 'L'){
                    pos++; // skip 'L'
                    while (pos < descriptor.length() && descriptor.charAt(pos) != ';'){
                        pos++;
                    }
                    if (pos >= descriptor.length()){
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    pos++; // skip ';'
                }
                if (outputFrameStack.isEmpty()){
                    throw new IllegalStateException("Stack underflow while popping array");
                }
                outputFrameStack.pop();
            }else{ // primitive
                if (outputFrameStack.isEmpty()){
                    throw new IllegalStateException("Stack underflow while popping primitive");
                }
                outputFrameStack.pop();
            }
        }
    } catch (Exception ex){
        throw new IllegalStateException("Error while popping types from descriptor " + descriptor, ex);
    }
}

