private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
        } else {
            int bound = Math.abs(key.hashCode());
            bounds.add(bound);
        }
    }
    return bounds;
}

public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '{') {
            sb.append("%7B");
        } else if (ch == '}') {
            sb.append("%7D");
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

