public static String applyRelativePath(String path, String relativePath) {
    if (path == null) throw new IllegalArgumentException("path cannot be null");
    if (relativePath == null) throw new IllegalArgumentException("relativePath cannot be null");
    if (relativePath.isEmpty()) return path;
    // If relativePath starts with '/', treat as absolute path (root-relative)
    if (relativePath.startsWith("/")) {
        java.util.List<String> absParts = new java.util.ArrayList<>();
        for (String part : relativePath.split("/")) {
            if (part.isEmpty() || part.equals(".")) continue;
            if (part.equals("..")) {
                if (!absParts.isEmpty()) absParts.remove(absParts.size() - 1);
                continue;
            }
            absParts.add(part);
        }
        StringBuilder sb = new StringBuilder();
        sb.append("/");
        for (int i = 0; i < absParts.size(); i++) {
            if (i > 0) sb.append("/");
            sb.append(absParts.get(i));
        }
        return sb.toString();
    }
    boolean isAbsoluteBase = path.startsWith("/");
    java.util.List<String> parts = new java.util.ArrayList<>();
    for (String part : path.split("/")) {
        if (!part.isEmpty()) parts.add(part);
    }
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            } else if (!isAbsoluteBase) {
                parts.add(".."); // allow upward traversal when base is relative
            }
            continue;
        }
        parts.add(part);
    }
    StringBuilder sb = new StringBuilder();
    if (isAbsoluteBase) sb.append("/");
    for (int i = 0; i < parts.size(); i++) {
        if (i > 0) sb.append("/");
        sb.append(parts.get(i));
    }
    return sb.toString();
}

