static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    // Count non-null string elements
    int count = 0;
    for (Object obj : array) {
        if (obj != null && obj instanceof String) {
            count++;
        }
    }
    // If there are no non-null elements, return an empty array
    if (count == 0) {
        return new String[0];
    }
    // If array is already a String[] and contains no nulls, return it as is
    if (array instanceof String[] && count == array.length) {
        return (String[]) array;
    }
    // Create a new array without null elements
    String[] result = new String[count];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null && obj instanceof String) {
            result[idx++] = (String) obj;
        }
    }
    return result;
}

