public boolean isExpired(long timestamp, long expiredThreshold){
    try {
        // If threshold is negative, consider never expired
        if (expiredThreshold < 0) {
            return false;
        }
        long current = System.currentTimeMillis();
        // If the provided timestamp is in the future, it cannot be expired
        if (timestamp > current) {
            return false;
        }
        long diff = current - timestamp;
        // Prevent overflow issues by ensuring diff is non-negative
        if (diff < 0) {
            return false;
        }
        return diff > expiredThreshold;
    } catch (Exception e) {
        // In case of unexpected errors, default to not expired
        return false;
    }
}

Edge edgeToNext() {
    try {
        if (previousNode == null || nextNode == null) {
            return null;
        }
        Node from = previousNode;
        Node to = nextNode;
        if (from.isVirtual()) {
            from = from.getRealNode();
        }
        if (to.isVirtual()) {
            to = to.getRealNode();
        }
        return new Edge(from, to);
    } catch (Exception e) {
        // In case of any unexpected issue, return null to indicate failure
        return null;
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Handle null inputs gracefully
    if (str == null || substring == null) {
        return false;
    }

    int strLength = str.length();
    int subLength = substring.length();

    // Validate index bounds
    if (index < 0 || index > strLength) {
        return false;
    }

    // Empty substring always matches at any valid index
    if (subLength == 0) {
        return true;
    }

    // Ensure the substring fits within the original string
    if (index + subLength > strLength) {
        return false;
    }

    // Compare character by character
    for (int i = 0; i < subLength; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

protected void append(LoggingEvent event){
    // Guard against null event
    if (event == null) {
        return;
    }

    // Retrieve the message from the event, handling any potential exceptions
    String message;
    try {
        message = event.getFormattedMessage();
    } catch (Exception ex) {
        // Fallback: use the raw message if formatted message fails
        Object raw = event.getMessage();
        message = raw == null ? null : raw.toString();
    }

    // If the message is null or empty, nothing to send
    if (message == null || message.isEmpty()) {
        return;
    }

    // If there are no connected clients, exit early
    if (connectedClients == null || connectedClients.isEmpty()) {
        return;
    }

    // Send the message to each connected client, handling individual failures gracefully
    for (Client client : connectedClients) {
        try {
            client.write(message);
        } catch (Exception ex) {
            // Log the failure without interrupting the loop
            System.err.println("Failed to write log message to client: " + ex);
        }
    }
}

