private void checkIfPackedField() throws IOException {
    // Packed repeated fields for primitive types are encoded with a length-delimited
    // wire type (value 2).  This method checks the current tag's wire type
    // and, if it indicates a packed field, updates the internal state
    // so that subsequent reads treat the data as a packed sequence.
    //
    // The actual implementation details (field, constants, etc.) will
    // depend on the surrounding reader implementation.  Here we
    // conservatively use the common wire type value and a boolean flag.
    if ((this.currentTag & 0x07) == 2) {     // 2 == WIRETYPE_LENGTH_DELIMITED
        this.isPacked = true;               // update internal state
    }
}

public int readTag() throws IOException {
    // Attempt to read the first byte of the varint tag
    int firstByte = input.read();
    if (firstByte == -1) {
        // EOF reached before any bytes were read
        return 0;
    }

    // Parse the first part of the varint
    int result = firstByte & 0x7F;
    if ((firstByte & 0x80) == 0) {
        // Single-byte tag
        return result;
    }

    // Handle multi-byte tags
    int shift = 7;
    while (shift < 32) {
        int nextByte = input.read();
        if (nextByte == -1) {
            // Incomplete tag – treat as corrupted input
            throw new EOFException("EOF while opening tag");
        }
        result |= (nextByte & 0x7F) << shift;
        if ((nextByte & 0x80) == 0) {
            // Tag fully read
            return result;
        }
        shift += 7;
    }

    // If we get here, the varint is malformed
    throw new IOException("Malformed varint encountered while reading tag");
}

