private String buildContentRange(){
    try {
        long start = this.offset;
        long chunk = this.chunkSize;
        long size = this.fileSize;
        if (start < 0 || chunk <= 0 || size <= 0) {
            return null;
        }
        long end = start + chunk - 1;
        if (end >= size) {
            end = size - 1;
        }
        return "bytes " + start + "-" + end + "/" + size;
    } catch (Exception e) {
        return null;
    }
}

public static java.util.List<ThreadSnapshot> parseFromFileWithTimeRange(java.io.File file, java.util.List<ProfileAnalyzeTimeRange> timeRanges) throws java.io.IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split("\\|", 2);
            if (parts.length < 1) continue;
            long ts;
            try {
                ts = Long.parseLong(parts[0].trim());
            } catch (NumberFormatException e) {
                continue;
            }
            boolean inRange = timeRanges == null || timeRanges.isEmpty();
            if (!inRange) {
                for (ProfileAnalyzeTimeRange r : timeRanges) {
                    try {
                        java.lang.reflect.Method getStart = r.getClass().getMethod("getStartTime");
                        java.lang.reflect.Method getEnd = r.getClass().getMethod("getEndTime");
                        long start = (long) getStart.invoke(r);
                        long end = (long) getEnd.invoke(r);
                        if (ts >= start && ts <= end) {
                            inRange = true;
                            break;
                        }
                    } catch (Exception ignored) {
                    }
                }
            }
            if (!inRange) continue;
            ThreadSnapshot snapshot = null;
            try {
                java.lang.reflect.Constructor<?> ctor = ThreadSnapshot.class.getConstructor(long.class, String.class);
                snapshot = (ThreadSnapshot) ctor.newInstance(ts, line.substring(parts[0].length() + 1));
            } catch (Exception e) {
                try {
                    snapshot = (ThreadSnapshot) ThreadSnapshot.class.getConstructor().newInstance();
                    try {
                        java.lang.reflect.Method setTs = ThreadSnapshot.class.getMethod("setTimestamp", long.class);
                        setTs.invoke(snapshot, ts);
                    } catch (Exception ignored) {
                    }
                    try {
                        java.lang.reflect.Method setData = ThreadSnapshot.class.getMethod("setRawData", String.class);
                        setData.invoke(snapshot, line.substring(parts[0].length() + 1));
                    } catch (Exception ignored) {
                    }
                } catch (Exception ignored) {
                    continue;
                }
            }
            if (snapshot != null) {
                result.add(snapshot);
            }
        }
    }
    return result;
}
